// Fuente única: catálogo maestro microProducts. Sin catálogo ATCC fijo ni opciones duplicadas.
let strainProducts=[],commercialLots=[];
const configuredStrains=()=>strainProducts.filter(p=>p.type==='Cepa de referencia').map(p=>{
 const link=String(p.strainLink||'');
 const atcc=String(p.strainAtcc||'').trim()||(link.match(/ATCC\s*([0-9]+)/i)||[])[1]||'';
 return {...p,atcc,species:String(p.strainSpecies||p.name||'').trim()};
}).filter(p=>p.atcc&&p.species).sort((a,b)=>a.species.localeCompare(b.species)||a.atcc.localeCompare(b.atcc));
const commercialEligible=(productId,when=today())=>commercialLots.filter(l=>l.productId===productId&&Number(l.quantity)>=1&&l.openedAt&&l.openedAt<=when&&(l.effectiveExpiry||l.expiry)>=when&&!['CUARENTENA','RECHAZADO','DESCARTADO'].includes(l.status)).sort((a,b)=>(a.effectiveExpiry||a.expiry).localeCompare(b.effectiveExpiry||b.expiry));
const strainState=p=>expired(p)?'VENCIDO':p.status!=='APTA'?'NO APTO':live(p)===0?'AGOTADO':p.expiry<=plus(today(),30)?'PRÓXIMO A VENCER':'VIGENTE';
const strainLedger=()=>[...preps.map(p=>({date:p.date,kind:'PREPARACIÓN',code:p.code,atcc:p.atcc,lot:p.code,entry:Number(p.quantity||0),exit:0,actor:p.actorCode||'',detail:p.commercialLotCode?'Origen comercial: '+p.commercialLotCode:'Origen comercial no vinculado (registro anterior)'})),...reactivations.map(r=>({date:r.date,kind:'REACTIVACIÓN',code:r.code,atcc:r.atcc,lot:r.preparationCode,entry:0,exit:1,actor:r.actorCode||'',detail:'Consumo de 1 criovial · '+(r.activity||'')}))].sort((a,b)=>b.date.localeCompare(a.date)||b.code.localeCompare(a.code));
const strainOptions=()=>configuredStrains().map(p=>[p.id,`${p.species} · ATCC ${p.atcc}${p.manufacturer?' · '+p.manufacturer:''}`]);
const BHI_PREP_ML=10,BHI_REACT_ML=5;
// Excepción controlada: BHI pendiente de rendimiento se permite SOLO para preparar inóculos de QC.
const bhiQcEligible=p=>p.mediumId==='BHI'&&p.qc==='CONFORME'&&['PENDIENTE','LIBERADO','LIBERADO_HISTORICO'].includes(p.status)&&!['NO_CONFORME','RECHAZADO'].includes(p.performance);
const bhiAvailable=(when,amount)=>media.filter(p=>p.mediumId==='BHI'&&bhiQcEligible(p)&&p.date<=when&&p.expiry>=when&&Number(p.volume||0)-Number(p.bhiUsedMl||0)>=amount).sort((a,b)=>a.expiry.localeCompare(b.expiry));
const bhiSelect=(when,amount)=>{const eligible=bhiAvailable(when,amount);return `<div class="strain256-bhi"><div class="strain256-bhi-head"><div><strong>Caldo BHI para inóculo de control</strong><small>Consumo documentado: ${amount} mL · Seleccione un lote apto</small></div><span class="strain256-bhi-tag ${eligible.length?'is-available':'is-missing'}">${eligible.length?`${eligible.length} lote(s) elegible(s)`:'Sin lote elegible'}</span></div><label class="strain256-bhi-field">Lote BHI preparado<select name="bhiPreparationId" required>${options(eligible.map(p=>[p.id,`${p.code||p.id} · vence ${p.expiry} · saldo ${Math.max(0,Number(p.volume||0)-Number(p.bhiUsedMl||0))} mL`]),'Seleccione lote BHI apto')}</select></label>${!eligible.length?`<div class="strain256-bhi-alert" role="status">No existe BHI apto para ${E(when)}. Registre o revise un lote antes de continuar.</div>`:''}<details class="strain256-bhi-details"><summary>Ver requisitos de elegibilidad</summary><p>El lote debe estar preparado antes o en la fecha seleccionada, vigente, con QC conforme y saldo suficiente. Se admite rendimiento pendiente para preparar inóculos de control; se bloquean lotes rechazados o vencidos. Los lotes históricos solo se consideran si estaban vigentes en la fecha declarada.</p></details></div>`};

let strainModalOpen=false;let qcDirectPending=false;let qcSelectionApplied=false;let selectedPrepDate=today();let selectedReactDate=today();let reactStartClock=localClock();let reactStartDateManual=false;let reactDateEditing=false;let host,user,profile,tab='prepare',preps=[],reactivations=[],media=[],uses=[],off=[],note='',context=null,busy=false;
const canWrite=()=>['ADMIN','JEFE'].includes(profile?.role)||profile?.permissions?.strains==='WRITE';
const options=(arr,placeholder)=>`<option value="">${E(placeholder)}</option>`+arr.map(([id,label])=>`<option value="${E(id)}">${E(label)}</option>`).join('');
const released=(p,when=today())=>p.mediumId==='AN'&&['LIBERADO','LIBERADO_HISTORICO'].includes(p.status)&&p.qc==='CONFORME'&&!!p.date&&p.date<=when&&p.expiry>=when&&(p.performanceRequired===false||p.performance==='NO_APLICA');
const countUsed=id=>uses.filter(u=>u.preparationId===id).length;
