 const open=()=>{strainModalOpen=true;form.classList.add('strain255-opened');document.body.classList.add('strain255-lock');form.setAttribute('role','dialog');form.setAttribute('aria-modal','true');form.setAttribute('aria-label',tab==='reactivate'?'Reactivación documentada de cepa':'Preparación documentada de cepa');};
