function openReactionDossier(r){
 const prep=preps.find(p=>p.id===r.preparationId||p.code===r.preparationCode);
 const an=media.find(p=>p.id===r.anId);
 const bhi=media.find(p=>p.id===r.bhiPreparationId);
 const linkedUses=uses.filter(u=>u.reactivationId===r.id);
 const fmt=v=>{if(!v)return 'No registrado';if(typeof v?.toDate==='function')return v.toDate().toLocaleString('es-EC');if(typeof v==='object'&&Number.isFinite(v.seconds))return new Date(v.seconds*1000).toLocaleString('es-EC');return String(v)};
 const cell=(label,value)=>`<div class="strain258-field"><small>${E(label)}</small><strong>${E(fmt(value))}</strong></div>`;
 const section=(title,fields)=>`<section class="strain258-section"><h3>${E(title)}</h3><div class="strain258-grid">${fields.join('')}</div></section>`;
 const modal=document.createElement('div');modal.className='strain258-overlay';modal.setAttribute('role','presentation');
 const status=r.validUntil<today()?'VENCIDA':r.status||'SIN EVALUAR';
 modal.innerHTML=`<article class="strain258-dialog" role="dialog" aria-modal="true" aria-label="Expediente de reactivación ${E(r.code||r.id)}" tabindex="-1"><header class="strain258-head"><div><small>LAB-PSI · CEPAS DE REFERENCIA · SOLO LECTURA</small><h2>Expediente de reactivación</h2><p>${E(r.code||r.id)} · ${E(r.species||prep?.species||'Cepa de referencia')} · ATCC ${E(r.atcc||prep?.atcc||'—')}</p></div><button type="button" class="strain258-close" aria-label="Cerrar expediente">✕</button></header><div class="strain258-body"><div class="strain258-banner"><strong>Estado actual: ${E(status)}</strong><span>Evaluación original: ${E(r.status||'No registrada')} · Consulta documental, sin cambios de inventario</span></div>
 ${section('01 · Identificación y criovial utilizado',[cell('Registro',r.code||r.id),cell('Cepa',r.species||prep?.species),cell('ATCC',r.atcc||prep?.atcc),cell('Preparación de origen',r.preparationCode||prep?.code),cell('Fecha de preparación',prep?.date),cell('Caducidad de la preparación',prep?.expiry),cell('Crioviales preparados en origen',prep?.quantity)])}
 ${section('02 · Reactivación y vigencia',[cell('Fecha de reactivación',r.reactivationDate||r.date),cell('Válido hasta',r.validUntil||r.expiry),cell('Tipo de registro',r.historicalEntry?'Histórico':'Corriente'),cell('Inicio de incubación',r.incubationStart),cell('Fin de incubación',r.incubationEnd),cell('Duración (h)',r.incubationHours),cell('Temperatura de incubación (°C)',r.incubationTemperature)])}
 ${section('03 · Recursos y consumos documentados',[cell('Criovial descontado',r.preparationCode||prep?.code),cell('Cantidad descontada','1 criovial'),cell('Medio AN / lote',r.anCode||an?.code),cell('Caja AN',r.anBox),cell('Consumo de AN',linkedUses.length?linkedUses.length+' caja(s) registrada(s)':'1 caja declarada; vínculo histórico no disponible'),cell('BHI / lote',bhi?.code||r.bhiPreparationId),cell('Volumen BHI (mL)',r.bhiConsumedMl),cell('Registro de consumo AN',linkedUses.map(u=>u.id).join(', ')||'No vinculado en datos cargados')])}
 ${section('04 · Resultados y evaluación original',[cell('Estado de evaluación',r.status),cell('Morfología',r.morphology),cell('Crecimiento',r.growth),cell('Lectura BHI sin inóculo',r.bhiBlank),cell('Lectura BHI inoculado',r.bhiInoculated),cell('Diferencia BHI',r.bhiNet),cell('Evaluación BHI',r.bhiEvaluation),cell('Concentración final',r.finalConcentration||r.concentration),cell('Método / criterio',r.concentrationMethod)])}
 ${section('05 · Responsables y trazabilidad',[cell('Responsable del registro',r.actorCode),cell('Verificado por',r.verifiedBy),cell('Actividad',r.activity),cell('Destino',r.destination),cell('Fecha real de registro',r.createdAt),cell('Referencia de vigencia',r.validityEvidence),cell('Observaciones',r.notes),cell('Identificador Firebase',r.id)])}
 <div class="strain258-disclaimer">Los datos mostrados corresponden al expediente registrado y a los recursos actualmente cargados. La consulta no autoriza reactivaciones vencidas ni altera las evaluaciones, los saldos o los movimientos anteriores.</div></div><footer class="strain258-footer"><button type="button" class="strain258-dismiss">Cerrar expediente</button></footer></article>`;
 const oldFocus=document.activeElement;document.body.append(modal);document.body.classList.add('strain258-lock');
 const close=()=>{modal.remove();document.body.classList.remove('strain258-lock');document.removeEventListener('keydown',onKey);if(oldFocus?.isConnected)oldFocus.focus()};
 const onKey=e=>{if(e.key==='Escape')close()};document.addEventListener('keydown',onKey);
 modal.querySelector('.strain258-close').addEventListener('click',close);modal.querySelector('.strain258-dismiss').addEventListener('click',close);
 modal.addEventListener('click',e=>{if(e.target===modal)close()});modal.querySelector('.strain258-dialog').focus();
}
async function takeBox(tx,anId,when=today()){ const ref=doc(db,'microMediaPreparations',anId),snap=await tx.get(ref);if(!snap.exists())throw Error('Lote AN inexistente');const p={id:anId,...snap.data()};if(!released(p,when))throw Error('El AN no está liberado, apto o vigente para la fecha del registro');const refs=Array.from({length:Number(p.count||0)},(_,i)=>doc(db,'microStrainAnUses',`${anId}_${i+1}`));const docs=await Promise.all(refs.map(r=>tx.get(r)));const i=docs.findIndex(d=>!d.exists());if(i<0||docs.filter(d=>d.exists()).length+Number(p.usedUnits||0)>=Number(p.count||0))throw Error('Sin cajas AN disponibles: considerar consumos y bajas del inventario');return {ref:refs[i],an:p,box:i+1};}
function applyBhi(tx,b){tx.update(b.ref,{bhiUsedMl:Number(b.data.bhiUsedMl||0)+b.amount,updatedAt:serverTimestamp(),updatedBy:user.uid});tx.set(b.usage,{bhiPreparationId:b.id,bhiCode:b.data.code||b.id,reference:b.reference,kind:b.kind,quantityMl:b.amount,date:b.when,purpose:'INOCULO_CONTROL_CALIDAD',bhiStatusAtUse:b.data.status,bhiPerformanceAtUse:b.data.performance||'PENDIENTE',actorUid:user.uid,actorCode:profile.userCode||user.email,createdAt:serverTimestamp()});}
async function takeBhi(tx,id,when,amount,reference,kind){
 if(!id)throw Error('Seleccione un lote BHI vigente para inóculo de control.');
 const ref=doc(db,'microMediaPreparations',id),snap=await tx.get(ref);
 if(!snap.exists())throw Error('El lote BHI no existe en Firebase.');
 const p=snap.data();
 if(p.mediumId!=='BHI'||!bhiQcEligible(p)||!p.date||p.date>when||!p.expiry||p.expiry<when)throw Error('BHI no apto para la fecha registrada: compruebe fecha de preparación, vencimiento, QC conforme y que no esté rechazado.');
 const remaining=Number(p.volume||0)-Number(p.bhiUsedMl||0);
 if(remaining<amount)throw Error('Saldo BHI insuficiente. Prepare un lote nuevo.');
 const usage=doc(db,'microStrainBhiUses',reference);
 return {ref,usage,data:p,id,when,amount,reference,kind};
}
async function savePrep(e){e.preventDefault();if(busy)return;const f=e.currentTarget,v=Object.fromEntries(new FormData(f));if(v.expiry!==plusMonths(v.date,3)||v.supplierExpiry<v.date||v.date>today()||v.openingDate>v.date) {note='La fecha de vencimiento no puede ser anterior a la preparación.';render();return;}const chosen=configuredStrains().find(x=>x.id===v.atcc);if(!chosen){note='Seleccione una cepa válida del Catálogo maestro con vínculo ATCC configurado.';render();return;}const species=chosen.species;const atcc=chosen.atcc;const net=Number(v.inoculumTurbidity)-Number(v.mcfarland);if(v.mcfarland===''||v.inoculumTurbidity===''||!Number.isFinite(net)||Number(v.mcfarland)<0||Number(v.inoculumTurbidity)<0){note='Registre ambas lecturas de turbidez en McFarland.';render();return;}busy=true;try{const prepRef=doc(collection(db,'microStrainPreparations'));const anId=v.anBox;await runTransaction(db,async tx=>{const commercialRef=doc(db,'microLots',v.commercialLotId);const commercialSnap=await tx.get(commercialRef);if(!commercialSnap.exists())throw Error('Vial comercial inexistente');const commercial=commercialSnap.data();if(v.openingDate!==commercial.openedAt||v.supplierBatch!==(commercial.batch||'')||v.supplierExpiry!==(commercial.effectiveExpiry||commercial.expiry))throw Error('Los datos comerciales cambiaron en Firebase. Actualice y seleccione nuevamente el lote.');if(commercial.productId!==chosen.id||!commercial.openedAt||commercial.openedAt>v.date||(commercial.effectiveExpiry||commercial.expiry)<v.date||Number(commercial.quantity)<1||['CUARENTENA','RECHAZADO','DESCARTADO'].includes(commercial.status))throw Error('Vial comercial no apto, sin apertura, vencido o agotado');const bhi=await takeBhi(tx,v.bhiPreparationId,v.date,BHI_PREP_ML,prepRef.id,'PREPARACION_CEPA');const b=await takeBox(tx,anId,v.date);applyBhi(tx,bhi);const movementRef=doc(collection(db,'microMovements'));tx.update(commercialRef,{quantity:Number(commercial.quantity)-1,updatedAt:serverTimestamp(),updatedBy:user.uid});tx.set(movementRef,{lotId:v.commercialLotId,productId:chosen.id,batch:commercial.batch||'',unit:commercial.unit||'unidad',quantity:1,kind:'CONSUMO',date:v.date,reference:'PREPARACION_CEPA · '+prepRef.id,actorUid:user.uid,actorCode:profile.userCode||user.email,createdAt:serverTimestamp()});const status=['morphology','growth','purity'].every(k=>v[k]==='CUMPLE')&&net>=1.8-1e-9&&net<=2.2+1e-9?'APTA':'NO_APTA';tx.set(b.ref,{preparationId:anId,box:b.box,purpose:'PREPARACION_CEPA',strainPreparationId:prepRef.id,actorUid:user.uid,createdAt:serverTimestamp()});tx.set(prepRef,{code:`CP-${prepRef.id.slice(0,9).toUpperCase()}`,atcc,species,productId:chosen.id,commercialLotId:v.commercialLotId,commercialLotCode:commercial.code||v.commercialLotId,commercialMovementId:movementRef.id,bhiPreparationId:v.bhiPreparationId,bhiConsumedMl:BHI_PREP_ML,date:v.date,expiry:plusMonths(v.date,3),shelfLifeMonths:3,supplierBatch:v.supplierBatch,supplierExpiry:v.supplierExpiry,stabilityEvidence:v.stabilityEvidence,quantity:Number(v.quantity)+Number(v.reserveQuantity||0),available:Number(v.quantity),reserveQuantity:Number(v.reserveQuantity||0),openingDate:v.openingDate,incubationStart:v.incubationStart||'',incubationHours:v.incubationHours||'',incubationTemperature:v.incubationTemperature||'',expectedMorphology:v.expectedMorphology||'',verifiedBy:v.verifiedBy||'',approvedBy:v.approvedBy||'',vialVolume:v.vialVolume||'',storageLocation:v.storageLocation||'',storageTemperature:v.storageTemperature||'',cryoprotectant:v.cryoprotectant||'',mcfarland:v.mcfarland||'',inoculumTurbidity:Number(v.inoculumTurbidity),netTurbidity:Number(net.toFixed(2)),turbidityTarget:2,turbidityTolerance:0.2,turbidityEvaluation:net>=1.8-1e-9&&net<=2.2+1e-9?'CUMPLE':'NO_CUMPLE',status,anId,anCode:b.an.code,anBox:b.box,morphology:v.morphology,growth:v.growth,purity:v.purity,evidence:'',actorUid:user.uid,actorCode:profile.userCode||user.email,createdAt:serverTimestamp()});});note='Preparación registrada: 1 vial comercial y 1 caja AN descontados de forma atómica. Caducidad de crioviales a 3 meses; caja AN descontada del saldo disponible de forma atómica. La caja queda identificada en microStrainAnUses.';tab='inventory';strainModalOpen=false;qcDirectPending=false;document.body.classList.remove('strain255-lock','strain258-lock');}catch(err){note='No se guardó ni descontó: '+err.message;}finally{busy=false;render();}}
async function saveReact(e){e.preventDefault();if(busy)return;const v=Object.fromEntries(new FormData(e.currentTarget));const net=Number(v.bhiInoculated)-Number(v.bhiBlank);if(!v.preparationId||!v.anId||v.validUntil!==plus(v.date,REACT_VALIDITY_DAYS)||v.date>today()){note='Verifique la fecha de reactivación y la validez documentada.';render();return;}if(v.bhiBlank===''||v.bhiInoculated===''||!Number.isFinite(net)||Number(v.bhiBlank)<0||Number(v.bhiInoculated)<0){note='Registre correctamente las dos lecturas BHI.';render();return;}if(!v.incubationStart||!(Number(v.incubationHours)>0)||!v.incubationTemperature||!/^1\.5e(?:-1|[0-7])$/.test(v.finalConcentration)){note='Complete la incubación y seleccione la concentración final.';render();return;}const status=['morphology','growth'].every(k=>v[k]==='CUMPLE')&&net>=0.4-1e-9&&net<=0.6+1e-9?'APTA':'NO_APTA';busy=true;try{const ref=doc(collection(db,'microStrainReactivations'));await runTransaction(db,async tx=>{const prepRef=doc(db,'microStrainPreparations',v.preparationId);const snap=await tx.get(prepRef);if(!snap.exists())throw Error('Preparación inexistente');const p=snap.data();if(p.status!=='APTA'||p.date>v.date||p.expiry<v.date||Number(p.available)<1)throw Error('Criovial vencido, no apto o agotado');const bhi=await takeBhi(tx,v.bhiPreparationId,v.date,BHI_REACT_ML,ref.id,'REACTIVACION_CEPA');const b=await takeBox(tx,v.anId,v.date);applyBhi(tx,bhi);tx.update(prepRef,{available:Number(p.available)-1,updatedAt:serverTimestamp(),updatedBy:user.uid});tx.set(b.ref,{preparationId:v.anId,box:b.box,purpose:'REACTIVACION',reactivationId:ref.id,actorUid:user.uid,createdAt:serverTimestamp()});tx.set(ref,{code:`REA-${ref.id.slice(0,9).toUpperCase()}`,atcc:p.atcc,species:p.species,preparationId:v.preparationId,preparationCode:p.code,bhiPreparationId:v.bhiPreparationId,bhiConsumedMl:BHI_REACT_ML,anId:v.anId,anCode:b.an.code,anBox:b.box,date:v.date,reactivationDate:v.date,historicalEntry:v.date<today(),validUntil:v.validUntil,expiry:v.validUntil,validityEvidence:'EI-LAB-PSI/20',validityDays:REACT_VALIDITY_DAYS,status,concentration:v.finalConcentration,initialConcentrationNominal:'1.5e8 UFC/mL',finalConcentration:v.finalConcentration,concentrationMethod:'Concentración nominal seleccionada; no equivale a recuento viable',bhiBlank:Number(v.bhiBlank),bhiInoculated:Number(v.bhiInoculated),bhiNet:Number(net.toFixed(2)),bhiTarget:0.5,bhiTolerance:0.1,bhiEvaluation:net>=0.4-1e-9&&net<=0.6+1e-9?'CUMPLE':'NO_CUMPLE',incubationStart:v.incubationStart,incubationHours:Number(v.incubationHours),incubationEnd:v.incubationEnd,incubationTemperature:Number(v.incubationTemperature),activity:v.activity,destination:context?.medium||'',verifiedBy:v.verifiedBy,notes:v.notes||'',morphology:v.morphology,growth:v.growth,evidence:'',actorUid:user.uid,actorCode:profile.userCode||user.email,createdAt:serverTimestamp()});});note=`Reactivación ${status} registrada. Se descontaron un criovial y una caja AN con trazabilidad.`;context=null;sessionStorage.removeItem('micro_reactivation_context');strainModalOpen=false;tab='summary';}catch(err){note='No se guardó ni descontó: '+err.message;}finally{busy=false;render();}}
export function openQcStrainReactivation(atcc){
 const code=String(atcc||'').trim();if(!code)return;
 context={atcc:code,medium:'Control de calidad',test:'Q1',origin:'qc-planner'};
 sessionStorage.setItem('micro_reactivation_context',JSON.stringify(context));
 tab='reactivate';selectedReactDate=today();strainModalOpen=true;qcDirectPending=true;
 if(host){render();const modal=host.querySelector('#strain-reactivate');if(modal){modal.classList.add('strain255-opened');document.body.classList.add('strain255-lock');}}
}
export function stopStrains(){strainModalOpen=false;document.body.classList.remove('strain255-lock','strain258-lock');off.forEach(fn=>fn());off=[];host=null;}
export function renderStrains(el,u,p){stopStrains();host=el;user=u;profile=p;context=JSON.parse(sessionStorage.getItem('micro_reactivation_context')||'null');sessionStorage.removeItem('micro_reactivation_context');qcDirectPending=!!(context?.origin==='qc-planner');qcSelectionApplied=false;strainModalOpen=qcDirectPending;tab=context?'reactivate':'prepare';selectedPrepDate=today();selectedReactDate=today();note='';strainProducts=[];render();for(const [key,name] of [['products','microProducts'],['commercialLots','microLots'],['preps','microStrainPreparations'],['reactivations','microStrainReactivations'],['media','microMediaPreparations'],['uses','microStrainAnUses']])off.push(onSnapshot(collection(db,name),s=>{const rows=s.docs.map(d=>({id:d.id,...d.data()}));if(key==='products')strainProducts=rows;if(key==='commercialLots')commercialLots=rows;if(key==='preps')preps=rows;if(key==='reactivations')reactivations=rows;if(key==='media')media=rows;if(key==='uses')uses=rows;render()},err=>{note=`Error de acceso a ${name}: ${err.message}. Revise las reglas de Firebase.`;render()}));}
